void fun(int x, int *y){
    x *= 10;                 // changes a copy
    *y *= 10;                // changes the caller's b
}

int a = 10, b = 20;
fun(a, &b);                  // a stays 10, b becomes 200

void makeFirstCharUpper(char x[]){
    x[0] = x[0] - 'a' + 'A';   // lowercase -> uppercase
}

char a[] = "programmer";
makeFirstCharUpper(a);
printf("%s
", a);             // Programmer

void minMax(int arr[], int n, int *min, int *max){
    *min = *max = arr[0];
    for(int i = 1; i < n; i++){
        if(arr[i] < *min) *min = arr[i];
        if(arr[i] > *max) *max = arr[i];
    }
}
int mn, mx;
minMax(arr, n, &mn, &mx);
